import * as vault from './core.js';
import {octopus,icon,HATS,ACCESSORIES,COLORS} from './art.js';
import {renderSection,bindSection} from './sections.js';
const $=s=>document.querySelector(s);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toISOString().slice(0,10);
const now=()=>new Date().toISOString();
const time=at=>new Date(at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'});
const dayRows=arr=>(arr||[]).filter(r=>r.at?.slice(0,10)===today());
const sum=(arr,key)=>arr.reduce((s,r)=>s+(Number(r[key])||0),0);
let mission=null,session=null,admin=null,page='overview',toastTimer,lastActive=Date.now(),lastReminder=Date.now(),loungeTimer=null;
let pendingInstall=null;
function offerWebInstall(){if(!pendingInstall||document.getElementById('install-app'))return;const actions=document.querySelector('.top-actions');if(!actions)return;const button=document.createElement('button');button.id='install-app';button.className='button small';button.textContent='Install app';button.onclick=async()=>{const prompt=pendingInstall;if(!prompt)return;await prompt.prompt();await prompt.userChoice;pendingInstall=null;button.remove();};actions.prepend(button);}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();pendingInstall=event;offerWebInstall();});
window.addEventListener('appinstalled',()=>{pendingInstall=null;document.getElementById('install-app')?.remove();toast('AstrOctopi is installed. Your little space is ready.');});
const reminderJobs=new Map();
function armReminders(){if(!session)return;const r=session.data.reminders,id=session.profile.id;if(!r.enabled){reminderJobs.delete(id);return;}const previous=reminderJobs.get(id);reminderJobs.set(id,{name:session.profile.name.split(' ')[0],interval:Math.max(30,Number(r.interval)||60),voice:!!r.voice,haptic:!!r.haptic,next:previous&&previous.interval===Number(r.interval)?previous.next:Date.now()+Math.max(30,Number(r.interval)||60)*60000});}
const profilesExample=[{name:'Luna Chen',role:'Mission commander',color:'#b6b1ef',pfp:'🌙'},{name:'Alex Rivera',role:'Flight engineer',color:'#a7d8d6',pfp:'🪐'},{name:'Amara Okafor',role:'Science officer',color:'#f4cda9',pfp:'🌻'},{name:'Noah Park',role:'Medical officer',color:'#b4c9e8',pfp:'🌊'}];
const nav=[['overview','dashboard','My overview'],['vitals','heart','Physiology'],['sleep','moon','Sleep & recovery'],['nutrition','food','Food & water'],['exercise','exercise','Movement'],['mind','brain','Mind & mood'],['pet','sparkles','My octopus']];
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function closeModal(){if($('#dialog-root form')?.dataset.busy)return;$('#dialog-root').innerHTML='';}
function modal(title,html,onSubmit,options={}){
 const previous=document.activeElement;
 $('#dialog-root').innerHTML=`<div class="dialog-backdrop"><dialog open ${options.wide?'class="wide"':''} aria-labelledby="dialog-title" aria-modal="true"><div class="dialog-title"><h2 id="dialog-title">${escape(title)}</h2><button type="button" class="circle-button" id="dialog-close" aria-label="Close">${icon('plus',18).replace('class="','style="transform:rotate(45deg)" class="')}</button></div><form id="modal-form"><div class="stack">${html}</div><p class="dialog-error" role="alert" id="dialog-error"></p>${onSubmit?`<div class="dialog-actions"><button type="button" class="button" id="dialog-cancel">Cancel</button><button class="button primary" type="submit">${escape(options.submit||'Save')}</button></div>`:''}</form></dialog></div>`;
 const dismiss=()=>{closeModal();previous?.focus?.();};
 $('#dialog-close').onclick=dismiss;$('#dialog-cancel')?.addEventListener('click',dismiss);
 const form=$('#modal-form');form.querySelectorAll('div.field').forEach((field,index)=>{const label=field.querySelector('label'),control=field.querySelector('input,select,textarea');if(label&&control){if(!control.id)control.id='modal-field-'+index;label.htmlFor=control.id;}});
 if(onSubmit)form.onsubmit=async e=>{e.preventDefault();if(form.dataset.busy)return;form.dataset.busy='true';const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.dataset.label=submit.textContent;submit.textContent='One moment…';try{await onSubmit(new FormData(form));delete form.dataset.busy;closeModal();}catch(err){$('#dialog-error').textContent=err.message;delete form.dataset.busy;submit.disabled=false;submit.textContent=submit.dataset.label;}};
 $('#dialog-root').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();dismiss();}if(e.key==='Tab'){const items=[...$('#dialog-root').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}};
 setTimeout(()=>form.querySelector('input,select,textarea')?.focus(),50);
}
const pill=(state,label)=>`<span class="pill ${state}"><span class="status-dot"></span>${label||({green:'In range',yellow:'Review',red:'Urgent review',unknown:'No assessment'}[state])}</span>`;
function topbar(){return `<header class="topbar"><button class="brand" id="brand-home" aria-label="AstrOctopi crew home"><span class="brand-mark">${octopus({size:37,color:'#a7bde1'})}</span><span>AstrOctopi<small>A LITTLE SPACE FOR WELLBEING</small></span></button><div class="top-status"><span class="live"><span></span> Device-local console</span><span>${icon('shield',14)} Encrypted crew records</span></div><div class="top-actions"><span class="top-date">${new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'})} · UTC</span>${session||admin?`<button class="button small" id="lock-profile">${icon('lock',13)} Lock & switch</button>`:`<span class="pill">MISSION CONSOLE</span>`}</div></header>${mission?.demo?'<div class="demo-banner">Fictional demo mission · Sample readings and example ranges · No medical devices connected</div>':''}`;}
function bindTop(){ offerWebInstall();$('#brand-home').onclick=()=>lockHome();$('#lock-profile')?.addEventListener('click',lockHome);}
function lockHome(){vault.lock();session=null;admin=null;page='overview';clearInterval(loungeTimer);lastReminder=Date.now();renderHome();}
function renderHome(){const oldMission=mission?.id;mission=vault.getMission();if(oldMission!==mission?.id)reminderJobs.clear();const ps=mission?.profiles||profilesExample;
 $('#app').innerHTML=topbar()+`<main class="profile-page"><div class="profile-intro"><div class="eyebrow">${mission?escape(mission.name):'WELCOME TO YOUR ORBIT'}</div><h1>A little space for <span style="color:#8ca8ce">every body.</span></h1><p>Big missions begin with small moments of care. Who’s checking in?</p></div><div class="crew-grid">${ps.map((p,i)=>`<button class="profile-card" data-profile="${escape(p.id||i)}"><div class="profile-portrait" style="background:${/^#[a-f0-9]{6}$/i.test(p.color)?p.color+'25':'#eef2fc'}"><span class="pfp-emoji">${escape(p.pfp)}</span>${octopus({color:p.color,hat:['astronaut','beanie','sunhat','headphones'][i%4],size:180})}</div><h3>${escape(p.name)}</h3><p>${escape(p.role)}</p><div class="profile-lock">${icon('lock',11)} Private profile</div></button>`).join('')}</div><div class="chooser-bottom">${!mission?`<button class="button primary" id="demo-launch">${icon('sparkles',15)} Explore the demo mission</button><button class="button" id="setup-mission">${icon('plus',15)} Set up my crew</button>`:`<button class="button" id="medical-login">${icon('shield',15)} Medical officer access</button><button class="button" id="backup">${icon('download',15)} Encrypted backup</button><button class="button" id="mission-tools">${icon('settings',15)} Mission settings</button>`}<button class="button" id="restore">Restore backup</button>${location.protocol!=='astroctopi:'?'<a class="button" href="./desktop.html">Download for Windows ↓</a>':''}</div><div class="lounge-strip"><div class="lounge-icon">✧</div><div><h3>A good crew is a connected crew.</h3><p>Take a breath, share a laugh, or discover something new about each other.</p></div><button class="button" id="open-lounge">Enter crew lounge ${icon('arrow',14)}</button></div><p class="privacy-note">${icon('lock',11)} Only names and chosen avatars appear here. Health logs stay private behind each crew member’s passcode.</p><p class="privacy-note">Demonstration app · Device-local storage · Reviewed mission procedures are required for operational use</p><p class="privacy-note"><a href="./astroctopi-source.zip" download>Download AstrOctopi source code ↓</a></p></main>`;
 bindTop();document.querySelectorAll('[data-profile]').forEach(el=>el.onclick=async()=>{if(!mission){try{await createDemo();loginProfile(mission.profiles[Number(el.dataset.profile)]);}catch(e){toast(e.message);}}else loginProfile(mission.profiles.find(p=>p.id===el.dataset.profile));});
 $('#demo-launch')?.addEventListener('click',async e=>{e.target.disabled=true;try{await createDemo();loginProfile(mission.profiles[0]);}catch(err){toast(err.message);e.target.disabled=false;}});$('#setup-mission')?.addEventListener('click',setup);$('#medical-login')?.addEventListener('click',medicalLogin);$('#open-lounge').onclick=renderLounge;$('#backup')?.addEventListener('click',()=>download('astroctopi-encrypted-backup.json',vault.exportBackup()));$('#restore').onclick=restore;$('#mission-tools')?.addEventListener('click',missionTools);
}
async function createDemo(){await vault.demoMission();mission=vault.getMission();renderHome();}
function loginProfile(profile){modal(`Welcome, ${profile.name.split(' ')[0]}.`,`<p class="dialog-intro">Your wellbeing is your space. Enter your private passcode to continue.</p>${mission.demo?'<div class="notice yellow">Fictional demo · All crew passcodes: <b>123456</b></div>':''}<div class="field"><label for="profile-pin">Profile passcode</label><input id="profile-pin" name="pin" type="password" minlength="6" maxlength="200" autocomplete="current-password" required placeholder="Enter your passcode"></div><p class="form-help">Records are decrypted on this device only. The console locks after 5 minutes without input.</p>`,async fd=>{session=await vault.unlockProfile(profile.id,String(fd.get('pin')));admin=null;page='overview';lastActive=Date.now();lastReminder=Date.now();renderApp();},{submit:'Unlock my space'});}
function setup(){modal('Prepare your mission',`<p class="dialog-intro">Create 1–4 crew profiles on this console. Use unique passcodes with at least 6 characters; longer passphrases protect records better. Save the medical passphrase separately: there is no password recovery.</p><div class="form-grid"><div class="field"><label>Mission name</label><input name="mission" value="Asteria expedition" maxlength="60" required></div><div class="field"><label>Crew size</label><select id="crew-size" name="count"><option>1</option><option>2</option><option>3</option><option selected>4</option></select></div><div class="field full"><label>Authorized medical officer passphrase</label><input name="admin" type="password" minlength="10" maxlength="200" required autocomplete="new-password" placeholder="At least 10 characters"></div></div>${profilesExample.map((p,i)=>`<div class="crew-form-row" data-crew-form="${i}"><h4>Crew member ${i+1}</h4><div class="field"><label>Name</label><input name="name${i}" maxlength="60" value="${p.name}" required></div><div class="field"><label>Role</label><input name="role${i}" maxlength="60" value="${p.role}" required></div><div class="field"><label>Private passcode</label><input name="pin${i}" type="password" minlength="6" maxlength="200" required autocomplete="new-password"></div><div class="field"><label>Profile picture</label><select name="pfp${i}">${['🌙','🪐','🌻','🌊','🚀','🐱','🌎','⭐','🦋','🌸'].map(x=>`<option ${x===p.pfp?'selected':''}>${x}</option>`).join('')}</select></div></div>`).join('')}`,async fd=>{const count=Number(fd.get('count'));const ps=Array.from({length:count},(_,i)=>({name:fd.get('name'+i),role:fd.get('role'+i),pin:fd.get('pin'+i),pfp:fd.get('pfp'+i),color:profilesExample[i].color}));await vault.setupMission({name:fd.get('mission'),adminPass:fd.get('admin'),profiles:ps});renderHome();toast('Your mission is ready. Pick your profile to begin.');},{wide:true,submit:'Create my mission'});
 $('#crew-size').onchange=e=>{document.querySelectorAll('[data-crew-form]').forEach((row,i)=>{row.hidden=i>=Number(e.target.value);row.querySelectorAll('input').forEach(input=>input.disabled=row.hidden);});};}
function missionTools(){modal('Mission settings',`<p class="dialog-intro">This browser is the mission’s data store. An encrypted backup preserves health records, names, and avatar choices. Passcodes are still needed after restoring.</p><button type="button" class="button" id="tools-backup">Download encrypted mission backup</button><button type="button" class="button" id="source-download">Download app source</button><div class="notice">Demo access codes are public. For private logs, start a new mission with your own credentials.</div><button type="button" class="button danger" id="replace-mission">Clear local mission & start fresh</button>`);$('#tools-backup').onclick=()=>download('astroctopi-encrypted-backup.json',vault.exportBackup());$('#source-download').onclick=()=>{const a=document.createElement('a');a.href='./astroctopi-source.zip';a.download='astroctopi-source.zip';a.click();};$('#replace-mission').onclick=()=>{if(mission.demo){if(confirm('Clear this fictional demo mission?')){vault.resetMission();closeModal();renderHome();setup();}return;}modal('Authorize mission reset',`<p class="dialog-intro">Clearing removes every local crew record. Export an encrypted backup first. The designated medical passphrase is required.</p><div class="field"><label>Medical passphrase</label><input type="password" name="pass" required minlength="6" autocomplete="current-password"></div><label class="check"><input type="checkbox" name="confirm" required>I understand this removes the mission from this browser.</label>`,async fd=>{await vault.unlockAdmin(String(fd.get('pass')));vault.resetMission();session=null;admin=null;renderHome();toast('Local mission cleared. Set up your new crew when ready.');},{submit:'Clear local mission'});};}
function restore(){modal('Restore an encrypted mission',`<p class="dialog-intro">Choose an AstrOctopi encrypted backup. This replaces the mission stored in this browser; existing passcodes are required to unlock it.</p><div class="field"><label>Backup JSON file</label><input type="file" name="backup" accept=".json,application/json" required></div>`,async fd=>{const file=fd.get('backup');if(file.size>20000000)throw new Error('Choose a backup smaller than 20 MB.');if(mission&&!confirm('Replace this browser’s mission with the selected backup?'))throw new Error('Restore canceled.');vault.restoreBackup(await file.text());session=null;admin=null;renderHome();toast('Encrypted mission restored.');},{submit:'Restore mission'});}
async function persist(publicPatch={}){if(!session)throw new Error('Unlock a profile first.');await vault.saveProfile(session.profile.id,session.data,publicPatch);Object.assign(session.profile,publicPatch);renderApp();}
function renderApp(){if(!session)return renderHome();armReminders();const {profile,data}=session;const name=profile.name.split(' ')[0];
 $('#app').innerHTML=topbar()+`<div class="app-layout"><aside class="sidebar"><div><div class="sidebar-label">YOUR WELLBEING</div><nav class="side-nav">${nav.map(([id,ic,label])=>`<button class="nav-item ${page===id?'active':''}" ${page===id?'aria-current="page"':''} data-page="${id}">${icon(ic,18)}<span>${label}</span>${page===id?'<i class="nav-mark"></i>':''}</button>`).join('')}</nav></div><div><div class="sidebar-label">MISSION SUPPORT</div><nav class="side-nav"><button class="nav-item ${page==='learn'?'active':''}" data-page="learn">${icon('info',18)}<span>Space health guide</span></button><button class="nav-item ${page==='settings'?'active':''}" data-page="settings">${icon('settings',18)}<span>My preferences</span></button></nav></div><div class="side-bottom"><div class="side-pet">${octopus({color:data.pet.color,hat:data.pet.hat,accessory:data.pet.accessory,size:85})}<p>A little care goes a long way.</p><button class="text-button" data-page="pet">Visit ${escape(data.pet.name)} ${icon('arrow',11)}</button></div><div class="crew-mini"><div class="mini-avatar">${escape(profile.pfp)}</div><div><b>${escape(profile.name)}</b><small>${escape(profile.role)}</small></div></div></div></aside><main class="main"><div id="section-content"></div><footer class="app-foot"><span>${icon('shield',11)} Your records stay on this device.</span><span>EXPLORATION PROTOTYPE · NOT A MEDICAL DEVICE</span><button class="text-button tiny" data-page="settings">Preferences</button></footer></main></div>`;
 bindTop();const ctx={data,profile,save:()=>persist(),toast,modal,octopus,escape,refresh:renderApp};const content=$('#section-content');
 if(page==='overview'){content.innerHTML=overview();bindOverview();}else if(page==='vitals'){content.innerHTML=vitals();bindVitals();}else if(page==='pet'){content.innerHTML=petPage();bindPet();}else{content.innerHTML=renderSection(page,ctx);bindSection(page,ctx);}
 document.querySelectorAll('[data-page]').forEach(el=>el.addEventListener('click',()=>{page=el.dataset.page;renderApp();window.scrollTo(0,0);}));
}
function latest(id,data=session.data){return data.metrics.filter(m=>m.id===id).sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))[0];}
function state(m,data=session.data){return m?vault.metricStatus(m.id,m.value,m.context,m.at,data.ranges):'unknown';}
function alertList(data=session.data){return vault.METRICS.map(m=>({metric:m,reading:latest(m.id,data)})).filter(x=>state(x.reading,data)==='red');}
function alertBanner(){const reds=alertList();return reds.length?`<div class="alert-banner" role="alert">${icon('alert',23)}<div><b>! Urgent review: ${reds.map(x=>escape(x.metric.name)).join(', ')}</b>Outside the configured example range. Follow the mission medical procedure and contact the crew medical officer or flight surgeon. Concerning symptoms need attention even if a reading appears normal.</div><button class="button small" data-page="vitals">View</button></div>`:'';}
function spark(id){const a=session.data.metrics.filter(m=>m.id===id).sort((a,b)=>Date.parse(a.at)-Date.parse(b.at)).slice(-7).map(m=>m.value);if(a.length<2)return '';const min=Math.min(...a)-2,max=Math.max(...a)+2;const pts=a.map((v,i)=>`${i/(a.length-1)*75},${26-(v-min)/(max-min)*22}`).join(' ');return `<svg class="sparkline" viewBox="0 0 75 30" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="#b9ccdf" stroke-width="1.7" stroke-linecap="round"/></svg>`;}
function metricTile(id,label,ic,color){const m=latest(id);return `<div class="metric-card"><div class="metric-title"><span>${label}</span><span class="metric-icon ${color}">${icon(ic,15)}</span></div><div class="metric-value">${m?m.value:'—'}<small>${escape(vault.METRICS.find(x=>x.id===id).unit)}</small></div><div class="metric-bottom">${pill(state(m))}<small>${m?time(m.at)+' UTC':'Awaiting log'}</small></div></div>`;}
function overview(){const d=session.data;const water=sum(dayRows(d.water),'ml');const goal=d.goals.water||2500;const sleep=[...d.sleep].sort((a,b)=>b.date.localeCompare(a.date))[0];const sleepState=sleep&&sleep.date>=new Date(Date.now()-86400000).toISOString().slice(0,10)?(sleep.hours>=d.goals.sleep?'green':'yellow'):'unknown';const done=d.tasks.date===today()?d.tasks.done:[];const count=done.filter(id=>['vitals','water','move','mind'].includes(id)).length;const heartRate=latest('hr');
 return `<div class="greeting"><div><h1>Hey, ${escape(session.profile.name.split(' ')[0])} <span style="font-size:24px">☀</span></h1><p>A new day in orbit. A little care for you.</p></div><div class="date-badge">${icon('activity',13)} Your daily check-in</div></div>${alertBanner()}<div class="dashboard-top"><section class="hero"><div class="hero-content"><div class="eyebrow">YOU & YOUR LITTLE CO-PILOT</div><h2>Small steps.<br>Stellar wellbeing.</h2><p>${escape(d.pet.name)} is here for every sip, stretch, and moment of rest. Let’s find your rhythm today.</p><button class="button primary" id="daily-check">Start my check-in ${icon('arrow',14)}</button></div><div class="hero-art"><div class="orbit"></div><div class="orbit two"></div><span class="star a">✦</span><span class="star b">✧</span><span class="star c">✦</span><span class="star d">·</span>${octopus({color:d.pet.color,hat:d.pet.hat,accessory:d.pet.accessory})}</div></section><section class="card pet-card"><div><div class="card-head"><h3>${escape(d.pet.name)}’s little universe</h3><span class="pet-heart">♡</span></div><span class="pill" style="background:#f0e6b8;color:#95834a">${count>=3?'Feeling cared for':'Ready for today'}</span><p>Every caring action helps your companion thrive.</p></div><div><div class="pet-status-row"><span class="tiny muted">Daily care</span><div class="progress"><span style="width:${Math.min(count/4*100,100)}%"></span></div><b>${Math.min(count,4)}/4</b></div><p>Your octopus is always safe. Rest days count, too.</p><button class="text-button mt" data-page="pet">Make it your own ${icon('arrow',12)}</button></div></section></div><div class="metrics-heading"><h3>Your health, at a glance</h3><div class="legend"><span><i></i>In range</span><span><i class="amber"></i>Review</span><span><i class="red"></i>Urgent</span></div><button class="text-button" data-page="vitals">All measurements ${icon('arrow',12)}</button></div><div class="metrics-grid">${metricTile('hr','Resting heart rate','heart','')}${metricTile('spo2','Oxygen saturation','activity','blue')}<div class="metric-card"><div class="metric-title"><span>Last sleep</span><span class="metric-icon purple">${icon('moon',15)}</span></div><div class="metric-value">${sleep?sleep.hours:'—'}<small>hours</small></div><div class="metric-bottom">${pill(sleepState,sleepState==='green'?'Plan met':sleepState==='yellow'?'Below plan':'No recent log')}<small>${sleep?escape(sleep.date.slice(5)):'Awaiting log'}</small></div></div>${metricTile('temp','Body temperature','activity','yellow')}</div><div class="lower-grid"><section class="card small-card"><div class="card-head"><h3>${icon('check',17)} Today’s little wins</h3><span class="pill">${count}/4</span></div>${[['vitals','Morning measurements','Your personal medical plan','08:00'],['water','Hydration check-in','A small sip, a big difference','Now'],['move','Move your body','Follow your exercise plan','14:00'],['mind','A moment for your mind','How are you, really?','18:00']].map(([id,title,desc,t])=>`<div class="routine"><button class="task-check ${done.includes(id)?'done':''}" data-task="${id}" aria-label="${done.includes(id)?'Unmark':'Mark'} ${title}" aria-pressed="${done.includes(id)}">${done.includes(id)?icon('check',13):''}</button><div><b>${title}</b><small>${desc}</small></div><span class="task-time">${t}</span></div>`).join('')}</section><section class="card small-card"><div class="card-head"><h3>${icon('water',18)} Hydration station</h3><span class="pill">TODAY</span></div><div class="hydration-body"><div class="water-ring"><svg viewBox="0 0 112 112"><circle cx="56" cy="56" r="47" fill="none" stroke="#edf3fb" stroke-width="7"/><circle cx="56" cy="56" r="47" fill="none" stroke="#b5cfea" stroke-width="7" stroke-linecap="round" stroke-dasharray="${Math.min(water/goal,1)*295.3} 295.3"/></svg><span>${(water/1000).toFixed(2)}<small>of ${(goal/1000).toFixed(1)} L planned</small></span></div><span class="tiny muted">A little sip for your orbit.</span><button class="button soft" id="quick-water">${icon('plus',13)} Log 250 mL water</button></div></section><section class="card small-card tip-card"><div class="card-head"><h3>A cosmic pause</h3><span>✧</span></div><div class="tip-illustration">🪐<span>✦</span></div><p>Unclench your jaw. Let your shoulders soften. Take one slow, comfortable breath.<br>You have a little space here.</p><button class="text-button" data-page="sleep">Find your calm ${icon('arrow',12)}</button></section></div><div class="notice mt">Example color bands support this demonstration. A green value is not a diagnosis. Missing, stale, or unsuitable-context readings stay gray. ${heartRate?'Latest source: '+escape(heartRate.source)+'.':''}</div>`;}
function bindOverview(){$('#daily-check').onclick=()=>{page='vitals';renderApp();};$('#quick-water').onclick=async()=>{session.data.water.push({at:now(),ml:250});const stock=session.data.inventory.find(x=>x.id==='water');if(stock)stock.qty=Math.max(0,Number(stock.qty)-250/(Number(stock.ml)||250));await persist();toast('250 mL logged. One small sip for your orbit.');};document.querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{const d=session.data;if(d.tasks.date!==today())d.tasks={date:today(),done:[]};const id=b.dataset.task;d.tasks.done=d.tasks.done.includes(id)?d.tasks.done.filter(x=>x!==id):[...d.tasks.done,id];await persist();toast('Your little wins are saved.');});}
function vitals(){const d=session.data;return `<div class="page-title"><div><div class="eyebrow">PHYSIOLOGY</div><h1>Know your orbit.</h1><p>Real measurements, useful context, and a little clarity.</p></div><button class="button" id="import-readings">${icon('plus',14)} Import readings</button></div>${alertBanner()}<div class="notice mb">${icon('info',14)} Example ranges · Flight-surgeon review required. No sensor is connected. Use a mission-approved device and enter its actual result. Incomplete context or stale readings remain gray.</div><div class="vital-grid">${vault.METRICS.map(m=>{const r=latest(m.id);const ranges=d.ranges?.[m.id]||m;return `<article class="card vital-card"><div class="row between"><h3>${escape(m.name)}</h3>${pill(state(r))}</div><div class="row between"><div class="metric-value">${r?r.value:'—'}<small>${escape(m.unit)}</small></div>${spark(m.id)}</div><p>${escape(m.description)}</p><div class="method"><span class="eyebrow">HOW IT’S MEASURED</span><p>${escape(m.method)}</p></div><p class="mt tiny">${r?`${escape(r.source)} · ${escape(r.context)}<br>${new Date(r.at).toLocaleString('en-GB',{timeZone:'UTC'})} UTC`:'No reading logged yet.'}</p><p class="tiny muted">Example in-range band: ${ranges.green[0]}–${ranges.green[1]} ${escape(m.unit)}</p><button class="button" data-log="${m.id}">${icon('plus',13)} Log measurement</button></article>`;}).join('')}</div><section class="card mt"><div class="card-head"><h3>Measurement log</h3><span class="pill">LATEST 20</span></div><div class="scroll"><table class="history-table"><thead><tr><th>Metric</th><th>Value</th><th>Method / source</th><th>Context</th><th>Recorded (UTC)</th></tr></thead><tbody>${[...d.metrics].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).slice(0,20).map(r=>`<tr><td>${escape(vault.METRICS.find(m=>m.id===r.id)?.name)}</td><td>${r.value}</td><td>${escape(r.source)}</td><td>${escape(r.context)}</td><td>${new Date(r.at).toLocaleString('en-GB',{timeZone:'UTC'})}</td></tr>`).join('')||'<tr><td colspan="5">Your logged measurements will appear here.</td></tr>'}</tbody></table></div></section>`;}
function logMetric(id){const m=vault.METRICS.find(x=>x.id===id);modal(`Log ${m.name.toLowerCase()}`,`<p class="dialog-intro">${escape(m.method)}. ${escape(m.description)}</p><div class="form-grid"><div class="field"><label>Value (${m.unit})</label><input type="number" name="value" step="${m.step}" min="${m.min}" max="${m.max}" required></div><div class="field"><label>Context</label><select name="context">${(id==='glucose'?['fasting','after-meal','unknown']:['resting','exercise','post-exercise','unknown']).map(v=>`<option>${v}</option>`).join('')}</select></div><div class="field full"><label>Measured at (UTC)</label><input type="datetime-local" name="at" value="${now().slice(0,16)}" max="${now().slice(0,16)}" required></div><div class="field full"><label>Device or measurement method</label><input name="source" maxlength="100" placeholder="e.g. Upper-arm cuff · manual entry" required></div></div>`,async fd=>{const at=new Date(fd.get('at')+':00Z').toISOString();if(Date.parse(at)>Date.now()+60000)throw new Error('Choose a measurement time in the past or present.');const source=String(fd.get('source')).trim();if(!source)throw new Error('Enter the device or measurement method.');session.data.metrics.push({id,value:Number(fd.get('value')),context:fd.get('context'),at,source});try{await persist();}catch(e){session.data.metrics.pop();throw e;}toast('Measurement saved privately.');},{submit:'Save measurement'});}
function bindVitals(){document.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>logMetric(b.dataset.log));$('#import-readings').onclick=()=>modal('Import device measurements',`<p class="dialog-intro">Import a JSON export from a trusted device or adapter. This is file import, not a live hardware connection. Every row needs an ID, value, ISO timestamp, context, and source. Units are fixed to those shown in the app.</p><div class="notice">IDs: hr (bpm), spo2 (%), systolic / diastolic (mmHg), temp (°C), respiratory (breaths/min), glucose (mg/dL).</div><div class="field"><label>Measurements JSON</label><textarea name="json" rows="8" required placeholder='[{"id":"hr","value":72,"at":"${now()}","context":"resting","source":"Approved ECG export"}]'></textarea></div><p class="form-help">Use resting context for vital-sign example bands, fasting for glucose. Other contexts remain gray.</p>`,async fd=>{let arr;try{arr=JSON.parse(fd.get('json'));}catch{throw new Error('Enter a valid JSON array.');}if(!Array.isArray(arr)||!arr.length||arr.length>500)throw new Error('Import 1–500 readings at a time.');const clean=arr.map(r=>{const metric=vault.METRICS.find(m=>m.id===r.id);if(!metric||typeof r.value!=='number'||!Number.isFinite(r.value)||r.value<metric.min||r.value>metric.max||!Number.isFinite(Date.parse(r.at))||Date.parse(r.at)>Date.now()+60000||typeof r.source!=='string'||!r.source.trim()||!['resting','fasting','after-meal','exercise','post-exercise','unknown'].includes(r.context))throw new Error('A row has an invalid value, timestamp, context, or source. Nothing was imported.');return{id:r.id,value:r.value,at:new Date(r.at).toISOString(),context:r.context,source:r.source.trim().slice(0,100)};});session.data.metrics.push(...clean);try{await persist();}catch(e){session.data.metrics.splice(-clean.length);throw e;}toast(`${clean.length} measurements imported.`);},{wide:true,submit:'Import measurements'});}
function petPage(){const p=session.data.pet;return `<div class="page-title"><div><div class="eyebrow">YOUR LITTLE CO-PILOT</div><h1>A friend for every orbit.</h1><p>Make ${escape(p.name)} feel like a little piece of you.</p></div><span class="pill green">♡ Always safe & loved</span></div><div class="pet-customize"><div class="pet-stage"><div class="orbit"></div><span class="star a">✧</span><span class="star b">✦</span>${octopus({color:p.color,hat:p.hat,accessory:p.accessory})}<h2>${escape(p.name)}</h2><p>Your tiny companion. Your very big adventure.</p></div><div class="card pet-controls"><div class="row between"><h3>The name’s…</h3><button class="text-button" id="rename-pet">Rename ${icon('arrow',12)}</button></div><div><div class="eyebrow">A SHADE OF YOU</div><div class="swatches">${COLORS.map(c=>`<button class="swatch ${p.color===c.hex?'selected':''}" style="background:${c.hex}" title="${escape(c.name)}" aria-label="${escape(c.name)}" data-color="${c.hex}"></button>`).join('')}</div></div><div><div class="eyebrow">HATS OFF TO SELF-CARE</div><div class="choice-grid">${HATS.map(h=>`<button class="choice ${p.hat===h.id?'selected':''}" data-hat="${h.id}">${escape(h.label)}</button>`).join('')}</div></div><div><div class="eyebrow">A LITTLE SOMETHING EXTRA</div><div class="choice-grid">${ACCESSORIES.map(a=>`<button class="choice ${p.accessory===a.id?'selected':''}" data-accessory="${a.id}">${escape(a.label)}</button>`).join('')}</div></div><button class="button" id="choose-pfp">${escape(session.profile.pfp)} Choose my public profile picture</button></div></div><div class="notice mt">Small habits help your octopus thrive. Missing a day never harms your companion, and health readings do not change its affection for you.</div>`;}
function bindPet(){for(const key of ['color','hat','accessory'])document.querySelectorAll(`[data-${key}]`).forEach(b=>b.onclick=async()=>{session.data.pet[key]=b.dataset[key];await persist();});$('#rename-pet').onclick=()=>modal('A name for your co-pilot',`<div class="field"><label>Octopus name</label><input name="name" maxlength="25" value="${escape(session.data.pet.name)}" required></div>`,async fd=>{session.data.pet.name=String(fd.get('name')).trim()||'Orbit';await persist();});$('#choose-pfp').onclick=()=>modal('Your little piece of home',`<p class="dialog-intro">This picture is visible on the shared crew screen. Choose what makes you smile.</p><div class="field"><label>Profile picture</label><select name="pfp">${['🌙','🪐','🌻','🌊','🚀','🐱','🌎','⭐','🦋','🌸'].map(x=>`<option ${x===session.profile.pfp?'selected':''}>${x}</option>`).join('')}</select></div>`,async fd=>persist({pfp:String(fd.get('pfp'))}));}
function medicalLogin(){modal('Authorized medical access',`<p class="dialog-intro">This passphrase unlocks every crew member’s encrypted records. Access is for the party designated during mission setup.</p>${mission.demo?'<div class="notice yellow">Demo medical passphrase: <b>mission-control</b></div>':''}<div class="field"><label>Medical passphrase</label><input name="pass" type="password" minlength="6" required autocomplete="current-password"></div>`,async fd=>{admin=await vault.unlockAdmin(String(fd.get('pass')));session=null;lastActive=Date.now();renderAdmin();},{submit:'Open medical console'});}
function renderAdmin(){const stores=new Map();for(const {data} of admin)for(const i of data.inventory){const current=stores.get(i.name)||0;stores.set(i.name,current+Number(i.qty||0));}$('#app').innerHTML=topbar()+`<main class="main"><div class="page-title"><div><div class="eyebrow">AUTHORIZED MEDICAL CONSOLE</div><h1>A view of the whole crew.</h1><p>Private overview · ${escape(mission.name)} · Example ranges require clinical configuration.</p></div><button class="button" id="admin-backup">${icon('download',14)} Encrypted backup</button></div><div class="admin-grid">${admin.map(({profile,data})=>`<section class="card"><div class="row between"><div class="row"><div class="mini-avatar">${escape(profile.pfp)}</div><div><h3>${escape(profile.name)}</h3><p class="muted tiny">${escape(profile.role)}</p></div></div>${pill(alertList(data).length?'red':'unknown',alertList(data).length?'! Urgent review':'Review individual context')}</div><div class="admin-crew-metrics">${vault.METRICS.map(m=>{const r=latest(m.id,data);return `<div class="admin-metric"><span class="muted">${escape(m.name)}</span><b>${r?r.value+' '+escape(m.unit):'No reading'}</b>${pill(state(r,data))}</div>`;}).join('')}</div><div class="row wrap mt"><button class="button small" data-admin-open="${profile.id}">Open full record ${icon('arrow',12)}</button><button class="button small" data-ranges="${profile.id}">Configure color bands</button></div></section>`).join('')}</div><section class="card mt"><h3>On-board food reserves</h3><p class="muted tiny mt">Sum of the encrypted personal ration allocations on this console. This demonstration is not a live spacecraft warehouse feed. Fluid intake logs do not measure tank levels.</p><div class="row wrap mt">${[...stores].map(([name,qty])=>`<span class="pill">${escape(name)} · ${qty} rations</span>`).join('')||'<span class="muted">No supplies entered.</span>'}</div></section></main>`;bindTop();$('#admin-backup').onclick=()=>download('astroctopi-encrypted-backup.json',vault.exportBackup());document.querySelectorAll('[data-admin-open]').forEach(b=>b.onclick=()=>{session=admin.find(r=>r.profile.id===b.dataset.adminOpen);admin=null;page='overview';renderApp();toast('Authorized medical access: viewing this crew record. Lock before leaving.');});document.querySelectorAll('[data-ranges]').forEach(b=>b.onclick=()=>configureRanges(admin.find(r=>r.profile.id===b.dataset.ranges)));}
function configureRanges(record){modal(`Color bands · ${record.profile.name}`,`<p class="dialog-intro">Authorized configuration only. These values are stored per astronaut; no NASA universal alarm standard is implied. Green must fit inside the yellow review band. Resting context and freshness checks still apply.</p><div class="field"><label>Metric</label><select id="range-metric" name="metric">${vault.METRICS.map(m=>`<option value="${m.id}">${m.name} (${m.unit})</option>`).join('')}</select></div><div class="form-grid" id="range-fields"></div>`,async fd=>{const m=vault.METRICS.find(x=>x.id===fd.get('metric'));const green=[Number(fd.get('gl')),Number(fd.get('gh'))],yellow=[Number(fd.get('yl')),Number(fd.get('yh'))];if(yellow[0]>green[0]||green[0]>green[1]||green[1]>yellow[1]||yellow[0]<m.min||yellow[1]>m.max)throw new Error('Bands must be ordered: yellow low ≤ green low ≤ green high ≤ yellow high, within the metric’s valid values.');record.data.ranges={...record.data.ranges,[m.id]:{green,yellow}};record.data.audit.push({at:now(),action:'Medical officer configured '+m.name+' color bands'});await vault.saveProfile(record.profile.id,record.data);renderAdmin();toast('Individual color bands saved.');},{wide:true,submit:'Save individual bands'});const update=()=>{const m=vault.METRICS.find(x=>x.id===$('#range-metric').value);const r=record.data.ranges?.[m.id]||m;$('#range-fields').innerHTML=[['Green minimum','gl',r.green[0]],['Green maximum','gh',r.green[1]],['Yellow minimum','yl',r.yellow[0]],['Yellow maximum','yh',r.yellow[1]]].map(([label,name,value])=>`<div class="field"><label for="band-${name}">${label}</label><input id="band-${name}" name="${name}" type="number" step="${m.step}" min="${m.min}" max="${m.max}" value="${value}" required></div>`).join('');};$('#range-metric').onchange=update;update();}
const activities=[{id:'orbit',emoji:'🪐',name:'One good orbit',time:'5 minutes',desc:'A light check-in about the small things that made today better.',steps:['Each person names one tiny win from today. Passing is always welcome.','Invite each person to thank someone for a helpful moment. Keep it specific and kind.','Choose one small thing you can do to make tomorrow easier for each other.']},{id:'story',emoji:'🚀',name:'Mission: improbable',time:'4 minutes',desc:'Build one wonderfully ridiculous space story, one sentence at a time.',steps:['Begin: “We opened the cargo hatch and discovered a very unusual visitor…”','Go around the crew. Each person adds one sentence. The next must include an unexpected object.','Give your story a title together. Award everyone an imaginary cosmic storytelling badge.']},{id:'earth',emoji:'🌎',name:'A little piece of Earth',time:'6 minutes',desc:'Swap favorite memories, songs, and places that feel like home.',steps:['Think of a sound, smell, or place on Earth that makes you smile.','Take turns sharing one memory. Others listen without advice or interruption. Passing is welcome.','Find one thing your memories have in common. End with a comfortable shared pause.']}];
function renderLounge(){vault.lock();session=null;admin=null;$('#app').innerHTML=topbar()+`<main class="lounge-page"><div class="page-title"><div><div class="eyebrow">THE CREW LOUNGE</div><h1>Same ship. Shared little moments.</h1><p>A bit of connection, a bit of play. No scores or health data here.</p></div><button class="button" id="back-crew">${icon('crew',15)} Crew home</button></div><div class="hero" style="min-height:190px"><div class="hero-content" style="width:75%"><div class="eyebrow">BETTER, TOGETHER</div><h2>A little gravity for your crew.</h2><p>All activities are optional. Anyone can pass, pause, or leave. Private mood logs are never used to publicly label crew tension.</p></div><div class="hero-art" style="width:25%">${octopus({color:'#a7d8d6',hat:'party',size:150})}</div></div><div class="activity-grid">${activities.map(a=>`<article class="card activity-card"><div class="activity-emoji">${a.emoji}</div><div><span class="eyebrow">${a.time}</span><h3>${a.name}</h3></div><p>${a.desc}</p><button class="button" data-activity="${a.id}">Let’s try it ${icon('arrow',13)}</button></article>`).join('')}</div><div class="notice">These are social activities, not a psychological evaluation. For a private concern, use the established crew-support or flight-surgeon channel.</div></main>`;bindTop();$('#back-crew').onclick=renderHome;document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>startActivity(activities.find(a=>a.id===b.dataset.activity)));}
function startActivity(a){let step=0;modal(a.name,`<div class="eyebrow" id="activity-step">PROMPT 1 OF 3</div><p class="guide-step" id="activity-prompt">${a.steps[0]}</p><div class="timer" id="activity-timer">00:00</div><div class="row" style="justify-content:center"><button type="button" class="button primary" id="activity-next">Next prompt ${icon('arrow',13)}</button></div><p class="muted tiny" style="text-align:center">Take your time. Anyone may pass.</p>`);const start=Date.now();clearInterval(loungeTimer);loungeTimer=setInterval(()=>{if(!$('#activity-timer'))return clearInterval(loungeTimer);const s=Math.floor((Date.now()-start)/1000);$('#activity-timer').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');},1000);$('#activity-next').onclick=()=>{step++;if(step===3){clearInterval(loungeTimer);closeModal();toast('A little more connected. Thanks for making space for each other.');return;}$('#activity-prompt').textContent=a.steps[step];$('#activity-step').textContent=`PROMPT ${step+1} OF 3`;if(step===2)$('#activity-next').textContent='Finish together ✧';};}
function download(filename,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
for(const event of ['pointerdown','keydown','touchstart'])document.addEventListener(event,()=>{lastActive=Date.now();},{passive:true});
setInterval(()=>{if((session||admin)&&Date.now()-lastActive>=300000){$('#dialog-root').innerHTML='';lockHome();toast('Your console locked to keep your space private.');}for(const job of reminderJobs.values()){if(Date.now()<job.next)continue;job.next=Date.now()+job.interval*60000;toast(`${job.name}, a gentle AstrOctopi reminder: check your personal routine when ready.`);if(job.haptic&&navigator.vibrate)navigator.vibrate([100,80,100]);if(job.voice&&'speechSynthesis'in window)speechSynthesis.speak(new SpeechSynthesisUtterance(`${job.name}, your AstrOctopi routine reminder is ready.`));}},10000);
window.addEventListener('pagehide',()=>vault.lock());
window.addEventListener('pageshow',event=>{if(event.persisted)lockHome();});
try{renderHome();}catch(err){$('#app').innerHTML=`<div class="profile-page"><h1>AstrOctopi needs a little help.</h1><p class="notice mt">${escape(err.message)}</p><p class="mt">Use a current browser with storage enabled. Encrypted records stay on this device.</p></div>`;}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
